// Requête au BOAMP : parutions récentes, avis de marché, départements et métiers ciblés. Rien d'IA ici.
const r = $('Réglages').first().json;
const f = $('Lancer la veille').isExecuted ? $('Lancer la veille').first().json : {};
const jours = Math.max(1, Math.min(60, parseInt(f.jours ?? r.jours_par_defaut, 10) || r.jours_par_defaut));
const depuis = $now.setZone('Europe/Paris').minus({ days: jours }).toISODate();
const q = s => '"' + String(s).replace(/"/g, '') + '"';
const metiers = [...r.descripteurs.map(d => 'descripteur_libelle=' + q(d)), ...r.mots_cles.map(m => 'search(objet, ' + q(m) + ')')].join(' or ');
const where = `dateparution >= date'${depuis}' and nature="APPEL_OFFRE" and code_departement in (${r.departements.map(q).join(',')}) and (${metiers})`;
return [{ json: { where, depuis, jours } }];

// Annonces encore ouvertes, jamais vues, dans la limite du jour. Délai restant calculé sans IA.
const r = $('Réglages').first().json;
const deja = new Set($('Annonces déjà vues').all().map(i => i.json.idweb).filter(Boolean));
const maintenant = $now.setZone('Europe/Paris');
const toutes = $('Interroger le BOAMP').first().json.results ?? [];
const ouvertes = toutes.map(a => {
  const limite = a.datelimitereponse ? DateTime.fromISO(a.datelimitereponse).setZone('Europe/Paris') : null;
  return { idweb: a.idweb, objet: a.objet, acheteur: a.nomacheteur, departements: (a.code_departement ?? []).join(', '), parution: a.dateparution,
    date_limite: limite ? limite.toISO() : null, date_limite_lisible: limite ? limite.setLocale('fr').toFormat("d LLLL 'à' HH'h'mm") : 'non précisée',
    jours_restants: limite ? Math.floor(limite.diff(maintenant, 'days').days) : null, descripteurs: (a.descripteur_libelle ?? []).join(', '),
    type_marche: (a.type_marche ?? []).join(', '), procedure: a.procedure_libelle ?? '', url: a.url_avis };
}).filter(a => a.jours_restants === null || a.jours_restants >= 0);
const nouvelles = ouvertes.filter(a => !deja.has(a.idweb)).slice(0, r.max_annonces);
$getWorkflowStaticData('global').bilan = { trouvees: toutes.length, ouvertes: ouvertes.length, deja_vues: ouvertes.length - ouvertes.filter(a => !deja.has(a.idweb)).length, total_api: $('Interroger le BOAMP').first().json.total_count ?? toutes.length };
return nouvelles.map(json => ({ json }));

