// Une ligne par annonce : données de l'annonce + avis de l'IA + règle fixe sur le délai.
const r = $('Réglages').first().json;
const annonces = $('Annonces nouvelles').all().map(i => i.json);
return $input.all().map((it, i) => {
  const a = annonces[i], ia = it.json.output ?? {};
  let score = Math.max(0, Math.min(100, Math.round(ia.pertinence ?? 0)));
  const alertes = [];
  if (a.jours_restants !== null && a.jours_restants < r.delai_minimum_jours) alertes.push('délai court : ' + a.jours_restants + ' jour(s)');
  const reco = { repondre: 'répondre', etudier: 'étudier', ignorer: 'ignorer' }[ia.recommandation] ?? 'étudier';
  return { json: { ...a, score, recommandation: reco, raison: ia.raison ?? '', lot_vise: ia.lot_vise ?? '', points: ia.points_attention ?? [], alertes, vu_le: $now.toISO() } };
});

// Synthèse du jour, triée par pertinence.
const b = $getWorkflowStaticData('global').bilan ?? {};
const a = $('Assembler').all().map(i => i.json).sort((x, y) => y.score - x.score);
return [{ json: { bilan: b, nb: a.length, priorite: a.filter(x => x.score >= 70), etudier: a.filter(x => x.score >= 45 && x.score < 70), ecartees: a.filter(x => x.score < 45),
  date: $now.setZone('Europe/Paris').setLocale('fr').toFormat('cccc d LLLL yyyy'), depuis: $('Construire la requête').first().json.depuis } }];

